# Long dictations: three passages in a row, like a real ramble.
_by = {e[0]: e for e in EN}
LONG = []
for lid, parts in [("l1", ("e01", "e22", "e21")), ("l2", ("e03", "e29", "e30")),
                   ("l3", ("e04", "e05", "e26")), ("l4", ("e15", "e16", "e45")),
                   ("l5", ("e17", "e18", "e37")), ("l6", ("e08", "e43", "e35"))]:
    LONG.append((lid, " ".join(_by[p][1] for p in parts),
                 [t for p in parts for t in _by[p][2]]))

